Phase0Deposit decode_deposit(const Bytes& b){check(b.size()==1240,"deposit SSZ size");Phase0Deposit d;for(size_t i=0;i<33;++i)std::copy_n(b.begin()+32*i,32,d.proof[i].begin());std::copy_n(b.begin()+1056,48,d.message.public_key.begin());std::copy_n(b.begin()+1104,32,d.message.withdrawal_credentials.begin());d.message.amount_gwei=little(b,1136,8);std::copy_n(b.begin()+1144,96,d.signature.begin());return d;}
